import{_ as a,o as s,c as n,ag as t}from"./chunks/framework.BFM5MFIQ.js";const h=JSON.parse('{"title":"Dice probability syntax","description":"Supported AnyDice syntax for the dice probability calculator.","frontmatter":{"title":"Dice probability syntax","description":"Supported AnyDice syntax for the dice probability calculator.","order":10},"headers":[],"relativePath":"en/reference/dice-probability-syntax.md","filePath":"en/reference/dice-probability-syntax.md"}'),o={name:"en/reference/dice-probability-syntax.md"};function d(i,e,p,l,c,r){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="dice-probability-syntax" tabindex="-1">Dice probability syntax <a class="header-anchor" href="#dice-probability-syntax" aria-label="Permalink to &quot;Dice probability syntax&quot;">​</a></h1><p>Supported syntax for the dice probability calculator.</p><h2 id="program-basics" tabindex="-1">Program basics <a class="header-anchor" href="#program-basics" aria-label="Permalink to &quot;Program basics&quot;">​</a></h2><p>A program is a sequence of statements. Variables are uppercase words and are assigned with a colon. Use <code>output</code> to add a result and <code>named</code> to give it a title.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>X: 3</span></span>
<span class="line"><span>output X + 1 named &quot;four&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DAMAGE: 2d6 + 3</span></span>
<span class="line"><span>output DAMAGE named &quot;sword damage&quot;</span></span></code></pre></div><ul><li>Comments use backslashes: <code>\\ this is ignored \\</code></li><li>Variables can be reassigned and are evaluated in order.</li><li><code>0</code> is false; any non-zero number is true.</li><li>Named outputs support <code>[VARIABLE]</code> interpolation, for example <code>named &quot;ability [P]&quot;</code>.</li></ul><h2 id="numbers-dice-and-operators" tabindex="-1">Numbers, dice and operators <a class="header-anchor" href="#numbers-dice-and-operators" aria-label="Permalink to &quot;Numbers, dice and operators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Syntax</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><code>+ - * /</code></td><td>Arithmetic. Integer division rounds toward zero.</td><td><code>output 2d6 + 3</code></td></tr><tr><td><code>^</code></td><td>Exponentiation with a non-negative integer exponent.</td><td><code>output 2 ^ 3</code></td></tr><tr><td><code>= != &lt; &gt; &lt;= &gt;=</code></td><td>Comparison. Produces a 0/1 die when applied to dice.</td><td><code>output 3d6 &gt;= 15</code></td></tr><tr><td><code>&amp;</code> | <code>!</code></td><td>Boolean and, or and not. Zero is false; any other number is true.</td><td><code>output 1d6 &gt; 3 &amp; 1d6 != 6</code></td></tr><tr><td><code>@</code></td><td>Position access on a sequence, dice collection or number digits.</td><td><code>output 1@3d6</code></td></tr><tr><td><code>#</code></td><td>Length of a sequence or dice collection; number of digits for a number.</td><td><code>output #(3d6)</code></td></tr><tr><td><code>d</code></td><td>Creates a die or a collection of dice.</td><td><code>output 4d6</code></td></tr><tr><td><code>..</code></td><td>Inclusive range inside a sequence literal.</td><td><code>{1..6}</code></td></tr><tr><td><code>:</code></td><td>Sequence repetition count, and the separator between a variable name and its value.</td><td><code>{1:4}</code>, <code>X: 3</code></td></tr></tbody></table><p><code>d6</code> is one six-sided die, <code>3d6</code> is a collection of three dice that are summed, and <code>d%</code> is a d100. Custom dice use a sequence such as <code>d{1,2,4,4}</code>. Any expression can provide the faces, for example <code>2d(1d4)</code>. The empty die is written <code>d{}</code>.</p><h2 id="sequences" tabindex="-1">Sequences <a class="header-anchor" href="#sequences" aria-label="Permalink to &quot;Sequences&quot;">​</a></h2><p>Sequences are written with braces. They preserve their written order; use <code>sort</code> when you want the position-order setting applied. Mathematical and boolean operations sum all elements of a sequence.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{1, 2, 3}</span></span>
<span class="line"><span>{1..6}</span></span>
<span class="line"><span>{1:4, 2, 3}</span></span>
<span class="line"><span>{1..3:2}</span></span>
<span class="line"><span>{{1,2,4}:2, 5, 6}</span></span>
<span class="line"><span>{d6}</span></span>
<span class="line"><span>{}</span></span></code></pre></div><h3 id="position-and-length" tabindex="-1">Position and length <a class="header-anchor" href="#position-and-length" aria-label="Permalink to &quot;Position and length&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 @ {2,4,6}    \\ 2 \\</span></span>
<span class="line"><span>3 @ {2,4,6}    \\ 6 \\</span></span>
<span class="line"><span>{1,3} @ {2,4,6} \\ 8 \\</span></span>
<span class="line"><span># {2,4,6}      \\ 3 \\</span></span>
<span class="line"><span>1 @ 246        \\ 2 \\</span></span>
<span class="line"><span># 1234         \\ 4 \\</span></span>
<span class="line"><span># (3d6)        \\ 3 \\</span></span>
<span class="line"><span>{1,2} @ 3d6</span></span></code></pre></div><p><code>set &quot;position order&quot; to &quot;lowest first&quot;</code> reverses dice positions and digit positions. It does not reorder sequence literals until <code>sort</code> is used.</p><h2 id="loops-and-conditionals" tabindex="-1">Loops and conditionals <a class="header-anchor" href="#loops-and-conditionals" aria-label="Permalink to &quot;Loops and conditionals&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>loop N over {1..4} {</span></span>
<span class="line"><span>  output Nd4 named &quot;[N]d4&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>X: 1</span></span>
<span class="line"><span>if X = 1 {</span></span>
<span class="line"><span>  output 1</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>else if X = 2 {</span></span>
<span class="line"><span>  output 2</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>else {</span></span>
<span class="line"><span>  output 1d6</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Conditions can use comparisons and boolean operators. <code>else if</code> is supported. A die cannot be used directly as an <code>if</code> condition; pass it to a function with a typed parameter when you need to expand it. Loops iterate over series or dice values.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><p>Function names are made of lowercase words and uppercase parameter variables. Invoke a function by putting its name and arguments in square brackets. A function returns as soon as <code>result:</code> is reached; without a <code>result</code> it returns the empty die.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>function: add A to B {</span></span>
<span class="line"><span>  result: A + B</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>output [add 1 to 2]</span></span>
<span class="line"><span>output [add d4 to d6]</span></span></code></pre></div><p>Parameter types control how values are converted. A parameter without a type receives the value unchanged:</p><ul><li><code>:n</code> — numbers. A sequence is summed; a die is expanded once per outcome.</li><li><code>:d</code> — dice. A number becomes a constant die; a sequence is summed and becomes a constant die.</li><li><code>:s</code> — sequences. A number becomes a one-element sequence; dice are expanded into all possible sorted rolls.</li></ul><p>Functions can recurse. The maximum depth is controlled with <code>set &quot;maximum function depth&quot; to N</code>. <code>output</code> and <code>set</code> are not allowed inside a function.</p><h2 id="function-library" tabindex="-1">Function library <a class="header-anchor" href="#function-library" aria-label="Permalink to &quot;Function library&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Function</th><th>Meaning</th></tr></thead><tbody><tr><td><code>[absolute NUMBER]</code></td><td>Absolute value.</td></tr><tr><td><code>[SEQUENCE contains NUMBER]</code></td><td>1 if the number occurs in the sequence, otherwise 0.</td></tr><tr><td><code>[count VALUES in SEQUENCE]</code></td><td>Counts occurrences; repeated values are counted repeatedly.</td></tr><tr><td><code>[explode DIE]</code></td><td>Keeps rolling when the maximum value is rolled.</td></tr><tr><td><code>[highest N of DICE]</code></td><td>Sum of the highest N values. Supports multiple pools with <code>and</code>.</td></tr><tr><td><code>[lowest N of DICE]</code></td><td>Sum of the lowest N values. Supports multiple pools with <code>and</code>.</td></tr><tr><td><code>[middle N of DICE]</code></td><td>Sum of the middle N values.</td></tr><tr><td><code>[highest of A and B]</code></td><td>Higher of two numbers; dice are expanded per outcome.</td></tr><tr><td><code>[lowest of A and B]</code></td><td>Lower of two numbers; dice are expanded per outcome.</td></tr><tr><td><code>[maximum of DIE]</code></td><td>Highest possible value on a die (0 for an empty die).</td></tr><tr><td><code>[minimum of DIE]</code></td><td>Lowest possible value on a die (engine extension).</td></tr><tr><td><code>[reverse SEQUENCE]</code></td><td>Reverses the sequence order.</td></tr><tr><td><code>[sort SEQUENCE]</code></td><td>Sorts using the position order setting.</td></tr></tbody></table><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set &quot;position order&quot; to &quot;highest first&quot;</span></span>
<span class="line"><span>set &quot;position order&quot; to &quot;lowest first&quot;</span></span>
<span class="line"><span>set &quot;explode depth&quot; to 2</span></span>
<span class="line"><span>set &quot;maximum function depth&quot; to 5</span></span></code></pre></div><p>Settings apply to the statements that follow them. The default position order is highest first.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><h3 id="_4d6-drop-lowest" tabindex="-1">4d6 drop lowest <a class="header-anchor" href="#_4d6-drop-lowest" aria-label="Permalink to &quot;4d6 drop lowest&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>output [highest 3 of 4d6] named &quot;4d6 drop lowest&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ABILITIES: 6 d [highest 3 of 4d6]</span></span>
<span class="line"><span>loop P over {1..6} {</span></span>
<span class="line"><span>  output P @ ABILITIES named &quot;Ability [P]&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="blades-in-the-dark" tabindex="-1">Blades in the Dark <a class="header-anchor" href="#blades-in-the-dark" aria-label="Permalink to &quot;Blades in the Dark&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>function: blades ROLL:s {</span></span>
<span class="line"><span>  if 1@ROLL = 6 {</span></span>
<span class="line"><span>    result: 2 + (2@ROLL = 6)</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  result: 1@ROLL &gt;= 4</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>output [blades 2d6] named &quot;0d&quot;</span></span>
<span class="line"><span>loop P over {1..7} {</span></span>
<span class="line"><span>  output [blades Pd6] named &quot;[P]d&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="exploding-dice" tabindex="-1">Exploding dice <a class="header-anchor" href="#exploding-dice" aria-label="Permalink to &quot;Exploding dice&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set &quot;explode depth&quot; to 3</span></span>
<span class="line"><span>output [explode d6] named &quot;one exploding d6&quot;</span></span>
<span class="line"><span>output 2d[explode d6] named &quot;two independent exploding dice&quot;</span></span></code></pre></div><h3 id="functions-and-type-casting" tabindex="-1">Functions and type casting <a class="header-anchor" href="#functions-and-type-casting" aria-label="Permalink to &quot;Functions and type casting&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>function: double N:n if above B:n {</span></span>
<span class="line"><span>  if N &gt; B { result: N + N }</span></span>
<span class="line"><span>  result: N</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>output [double d6 if above 3] named &quot;1, 2, 3, 8, 10, 12&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>function: ROLL:s count fives and above and subtract ones {</span></span>
<span class="line"><span>  result: (ROLL &gt;= 5) - (ROLL = 1)</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>output [3d6 count fives and above and subtract ones]</span></span></code></pre></div>`,38)])])}const b=a(o,[["render",d]]);export{h as __pageData,b as default};
